export type Programme = "all" | "dubbo_ewaste" | "repair_cafe" | "library_of_things";
export type LearningLesson = { id: string; title: string; idea: string; steps: string[]; practice: string };
export type LearningCourse = {
  id: string; programme: Programme; title: string; summary: string;
  duration: number; level: "Getting started" | "Building skills" | "Advanced";
  source: string; sourceLabel: string;
  lessons: LearningLesson[];
  check: { question: string; options: [string, string, string]; answer: number; explanation: string };
};
type LessonInput = [string, string, string, string];
function course(id: string, programme: Programme, title: string, summary: string, duration: number,
  level: LearningCourse["level"], source: string, lessons: [LessonInput,LessonInput,LessonInput],
  question: string, options: [string,string,string], answer: number, explanation: string): LearningCourse {
  return { id, programme, title, summary, duration, level, source,
    sourceLabel: source.split("/").pop()?.replace(/\.md$/, "").replace(/-/g, " ") ?? "Source notes",
    lessons: lessons.map(([title,idea,steps,practice], i) => ({
      id: "lesson-" + (i+1), title, idea, steps: steps.split("|"), practice,
    })),
    check: { question, options, answer, explanation } };
}
