export function getCourse(id: string) { return courses.find(c => c.id === id); }
export function courseProgress(course: LearningCourse, lessons: {course_slug:string;lesson_slug:string}[]) {
  const complete = course.lessons.filter(l => lessons.some(x => x.course_slug === course.id && x.lesson_slug === l.id)).length;
  return { complete, total: course.lessons.length, percent: Math.round(100*complete/course.lessons.length) };
}
